import { hexToOklch } from '@app/color-engine';
import { REFERENCE_SECTORS, type IndexedReference } from '@app/contracts';
import { canonicalMockup } from './mockups.js';
import { isNeutral } from './rank.js';

// Aggregated, image-free statistics of the private reference library: what real professional identities
// show, per sector. Small enough to commit (tools/references/derived/library-stats.json) and regenerated by
// tools/references/derive-stats.mjs. It carries no file name, id, source link, image or embedding.

export interface Share {
  name: string;
  // Share (0 to 1) of the references of the sector concerned.
  share: number;
}

export interface SectorStats {
  indexed: number;
  // Images collected for the sector (the manifest), indexed or not.
  collected: number;
  quality: number;
  kinds: Share[];
  sections: Share[];
  mockups: Share[];
  styles: Share[];
  headingTypes: Share[];
  backgrounds: Share[];
  whitespace: Share[];
  // Share of the palette colours per hue family ("neutral": paper white, black and greys).
  hues: Share[];
}

export interface LibraryStats {
  version: 1;
  total: number;
  sectors: Record<string, SectorStats>;
  // Sectors of the library with no indexed reference: the ranking there rests on related sectors only.
  unindexedSectors: string[];
}

const MOCKUP_LIMIT = 15;
const SECTION_LIMIT = 20;

const round = (value: number, digits = 3): number => {
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
};

function hueFamily(hex: string): string {
  if (isNeutral(hex)) return 'neutral';
  const { h } = hexToOklch(hex);
  if (h === null) return 'neutral';
  if (h >= 335 || h < 10) return 'pink';
  if (h < 40) return 'red';
  if (h < 80) return 'orange';
  if (h < 115) return 'yellow';
  if (h < 185) return 'green';
  if (h < 225) return 'cyan';
  if (h < 290) return 'blue';
  return 'purple';
}

function shares(counts: Map<string, number>, denominator: number, limit?: number): Share[] {
  return [...counts]
    .map(([name, count]) => ({ name, share: round(count / denominator) }))
    .sort((a, b) => b.share - a.share || a.name.localeCompare(b.name))
    .slice(0, limit);
}

function count<T>(items: readonly T[], keys: (item: T) => readonly string[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    for (const key of new Set(keys(item))) counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return counts;
}

function sectorStats(references: readonly IndexedReference[], collected: number): SectorStats {
  const total = references.length;
  const palette = count(
    references.flatMap((entry) => entry.card.palette.map((hex) => ({ hex }))),
    (colour) => [hueFamily(colour.hex)],
  );
  // `count` counts distinct families per item: with one colour per item it is a plain tally of colours.
  const colours = references.reduce((sum, entry) => sum + entry.card.palette.length, 0);
  return {
    indexed: total,
    collected,
    quality: total === 0 ? 0 : round(references.reduce((s, r) => s + r.card.quality, 0) / total, 2),
    kinds: shares(
      count(references, (r) => [r.card.kind]),
      total,
    ),
    sections: shares(
      count(references, (r) => r.card.sections),
      total,
      SECTION_LIMIT,
    ),
    mockups: shares(
      count(references, (r) => r.card.mockups.map(canonicalMockup)),
      total,
      MOCKUP_LIMIT,
    ),
    styles: shares(
      count(references, (r) => r.card.styles),
      total,
    ),
    headingTypes: shares(
      count(references, (r) => [r.card.headingType]),
      total,
    ),
    backgrounds: shares(
      count(references, (r) => [r.card.background]),
      total,
    ),
    whitespace: shares(
      count(references, (r) => [r.card.whitespace]),
      total,
    ),
    hues: shares(palette, colours),
  };
}

/** `collected`: number of images collected per sector (the manifest of the library), optional. */
export function deriveLibraryStats(
  library: readonly IndexedReference[],
  collected: Readonly<Record<string, number>> = {},
): LibraryStats {
  const names = [...new Set([...library.map((r) => r.sector), ...Object.keys(collected)])].sort();
  const sectors: Record<string, SectorStats> = {};
  for (const name of names) {
    sectors[name] = sectorStats(
      library.filter((entry) => entry.sector === name),
      collected[name] ?? 0,
    );
  }
  return {
    version: 1,
    total: library.length,
    sectors,
    unindexedSectors: REFERENCE_SECTORS.filter(
      (sector) => !library.some((r) => r.sector === sector),
    ),
  };
}
